class Solution {
public:
    int minimumPairRemoval(vector<int>& nums) {
        int n = nums.size();
        if (n <= 1) return 0;
        vector<long long> val(n);
        for (int i = 0; i < n; i++) val[i] = nums[i];
        vector<int> prv(n), nxt(n);
        vector<char> alive(n, 1);
        for (int i = 0; i < n; i++) { prv[i] = i - 1; nxt[i] = (i + 1 < n) ? i + 1 : -1; }
        set<pair<long long,int>> s;
        for (int i = 0; i + 1 < n; i++) s.insert({val[i] + val[i + 1], i});
        int bad = 0;
        for (int i = 0; i + 1 < n; i++) if (val[i] > val[i + 1]) bad++;
        auto isBad = [&](int i) -> bool {
            return i >= 0 && alive[i] && nxt[i] != -1 && val[i] > val[nxt[i]];
        };
        int ops = 0;
        while (bad > 0) {
            auto it = s.begin();
            long long sum = it->first;
            int l = it->second;
            s.erase(it);
            if (!alive[l] || nxt[l] == -1 || val[l] + val[nxt[l]] != sum) continue;
            int r = nxt[l], p = prv[l], nn = nxt[r];
            if (p != -1) {
                s.erase({val[p] + val[l], p});
                if (isBad(p)) bad--;
            }
            if (isBad(l)) bad--;
            if (isBad(r)) bad--;
            if (nn != -1) s.erase({val[r] + val[nn], r});
            val[l] += val[r];
            alive[r] = 0;
            nxt[l] = nn;
            if (nn != -1) prv[nn] = l;
            if (p != -1) {
                s.insert({val[p] + val[l], p});
                if (isBad(p)) bad++;
            }
            if (isBad(l)) bad++;
            if (nn != -1) s.insert({val[l] + val[nn], l});
            ops++;
        }
        return ops;
    }
};
